css:
.switch {
  font-size: 17px;
  position: relative;
  display: inline-block;
  width: 8.5em;
  height: 3.3em;
}

.switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.slider {
  position: absolute;
  cursor: pointer;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: #2c2c2c;
  transition: .4s;
  border-radius: 30px;
}

.slider::before {
  position: absolute;
  content: "";
  height: 28px;
  width: 28px;
  border-radius: 20px;
  left: 13px;
  bottom: 14px;
  background: linear-gradient(144deg,#af40ff,#5b42f3 50%,#00ddeb);
  transition: .4s;
}

.switch input:checked + .slider:before {
  transform: translateX(5.1em);
}

.intro {
  color: #fff;
  padding-right: 0.5em;
  font-size: 22px;
}
